def lexicographically_smallest_rotation(lst):
    n = len(lst)
    if n == 0:
        return []
    best = lst[:]
    for k in range(1, n):
        cand = lst[k:] + lst[:k]
        if cand < best:
            best = cand
    return best

def find_duplicates(lst):
    seen = set()
    added = set()
    result = []
    for x in lst:
        if x in seen and x not in added:
            result.append(x)
            added.add(x)
        seen.add(x)
    return result

def common_dedent(lines):
    non_empty = [l for l in lines if l.strip() != ""]
    if not non_empty:
        return list(lines)
    min_indent = min(len(l) - len(l.lstrip(" ")) for l in non_empty)
    return [l[min_indent:] if l.strip() != "" else l for l in lines]

