    if len(parts) >= 3 and parts[-1] == parts[-2] and parts[-1] != "":
        return ".".join(parts[:-1])
    return name

def trim_matching_ends(s, ch):
    i, j = 0, len(s)
    while i < j and s[i] == ch:
        i += 1
    while j > i and s[j - 1] == ch:
        j -= 1
    return s[i:j]

def alternating_sum(lst):
