def count_valid_dates_in_list(date_list):
    def is_valid(s):
        if not isinstance(s, str) or len(s) != 10 or s[4] != "-" or s[7] != "-":
            return False
        yp, mp, dp = s[0:4], s[5:7], s[8:10]
        if not (yp.isdigit() and mp.isdigit() and dp.isdigit()):
            return False
        y, m, d = int(yp), int(mp), int(dp)
        if m < 1 or m > 12:
            return False
        def is_leap(yr):
            return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
        dim = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]
        return 1 <= d <= dim
    return sum(1 for s in date_list if is_valid(s))

def count_primes_up_to(n):
    if n < 2:
        return 0
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return sum(sieve)

