def highest_peak_index(lst):
    peaks = [i for i in range(1, len(lst) - 1) if lst[i] > lst[i - 1] and lst[i] > lst[i + 1]]
    if not peaks:
        return -1
    best = peaks[0]
    for i in peaks:
        if lst[i] > lst[best]:
            best = i
    return best

def find_longest_common_suffix_length(a, b):
    n = min(len(a), len(b))
    i = 0
    while i < n and a[len(a) - 1 - i] == b[len(b) - 1 - i]:
        i += 1
    return i
